      "territory": "旧石器时代尚无国界与版图概念，早期人类活动遍及南北：华北（泥河湾、周口店、蓝田、丁村）、华中和西南（元谋、观音洞、巫山、郧县）、华南与东北（柳江、金牛山）均有遗址发现，呈现『南北并茂、多点开花』的分布格局。",
      "core": "黄河中下游与长江中下游河谷盆地，以及西南云贵高原的洞穴地带，是先民择水草丰美、靠近猎场与原料的栖居核心。",
