        "bio": "1. 出生与家世：京兆杜陵士族，隋昌州长史杜吒之子。\n2. 少年：聪悟好学，隋大业中举进士，任滏阳尉。\n3. 出仕与从军：弃官归唐，初入秦王府兵曹参军；经房玄龄力荐留任，与玄龄共参帷幄。\n4. 历任职官与贡献：贞观朝任尚书右仆射，善决断大事，「军国万机，皆出其手」；与房玄龄定策，裁处政务明快。\n5. 人生转折：630年病逝，年仅四十六，太宗痛哭辍朝；后绘像凌烟阁，与房并称「房谋杜断」。",
