        "bio": "1. 出生与家世：字退之，河阳人，郡望昌黎，世称韩昌黎；三岁丧父，由兄嫂抚养成人。\n2. 少年：刻苦自励，尽通六经百家之学，立志复古明道。\n3. 出仕与从军：792年进士及第，三试博学宏词不中；历任节度使推官、监察御史，因上《论天旱人饥状》贬阳山令。\n4. 历任职官与贡献：宪宗时随裴度平淮西吴元济，撰《平淮西碑》；任刑部侍郎；谏迎佛骨被贬潮州刺史，兴学除弊、造福一方；晚年官至吏部侍郎（世称韩吏部）。\n5. 人生转折：贬潮州刺史途中作《左迁至蓝关示侄孙湘》；晚年文名愈盛，卒谥「文」，从祀孔庙。",
        "bioContribution": "1. 倡「古文运动」，主张「文以载道」「惟陈言之务去」，扭转六朝骈俪浮靡文风。\n2. 名篇《师说》《马说》《原道》《进学解》等为古文典范，苏轼誉「文起八代之衰」。\n3. 位列唐宋八大家之首，门下推挽后进，开宋代文风之先。"
