        "bio": "出生与家世：辽宗室后裔，字晋卿，博通儒释。\n少年：通汉文经史、天文历算。\n出仕：成吉思汗召用，窝阔台时为中书令。\n功绩：定税制中书省、止屠城、用儒生、行汉法，保全中原。\n影响：治世贤相，救中原于兵燹。",
