        "bio": "出生与家世：名霑，字梦阮，号雪芹，满洲正白旗包衣；祖父曹寅为康熙宠臣、江宁织造。\n少年：生于织造府，亲历钟鸣鼎食；雍正初年曹家获罪抄没，家道骤落。\n出仕：出身内务府包衣，未入仕途，以笔墨自遣。\n功绩：晚年居北京西郊，贫病交加而著《红楼梦》，自谓『披阅十载，增删五次』。\n转折：幼子夭亡，贫病而卒；全书仅成前八十回，后四十回由高鹗续补。",
        "bioContribution": "① 创作《红楼梦》，中国古典长篇小说巅峰，世界文学瑰宝。\n② 以贾府兴衰写尽封建家族百态，出场人物逾九百。\n③ 诗词、园林、饮食、礼俗无所不精，堪称百科全书式巨著。\n④ 开创『红学』，影响近现代文学与学术研究。"
