        "bioContribution": "① 著《聊斋志异》近五百篇，志怪小说集大成之作。\n② 借狐鬼花妖讽喻世情，尖锐批判科举与吏治。\n③ 文言小说艺术高峰，泽被后世戏曲小说。\n④ 另有《聊斋俚曲》《农桑经》等，兼涉戏曲农学。"
