        "bio": "出生与家世：字敏轩，号粒民，出身科举世家，曾祖、祖辈多登进士。\n少年：早年生活优裕，二十三岁成秀才，后家道中落。\n出仕：厌恶科举，拒绝博学鸿词科荐举，弃举业纵情诗酒。\n功绩：移居南京，穷困潦倒而著《儒林外史》，讽科举百态。\n转折：晚年客居扬州，潦倒而终，《外史》成不朽讽刺巨著。",
